     1→// WGSL shader for backward pass (gradient computation).
     2→//
     3→// This shader reads intermediate values saved during the forward pass
     4→// (transmittances, alphas, Gaussian indices) and computes gradients
     5→// w.r.t. Gaussian parameters using the chain rule.
     6→//
     7→// Phase 2: Per-pixel gradient computation with per-workgroup accumulation.
     8→
     9→// Contribution structure (matches forward pass)
    10→struct Contribution {
    11→    transmittance: f32,       // T before this Gaussian
    12→    alpha: f32,               // α of this Gaussian
    13→    gaussian_idx: u32,        // Source Gaussian index
    14→    pad: u32,                 // Alignment
    15→}
    16→
    17→// Gradient structure for a single Gaussian (must match GradientGPU in Rust!)
    18→struct Gradient {
    19→    d_color: vec4<f32>,              // dL/d(color) + padding
    20→    d_opacity_logit_pad: vec4<f32>,  // dL/d(opacity_logit) + padding
    21→    d_mean_px: vec4<f32>,            // dL/d(mean_px) + padding
    22→    d_cov_2d: vec4<f32>,             // dL/d(cov_2d) + padding
    23→}
    24→
    25→// Gaussian 2D structure (same as rasterize.wgsl)
    26→struct Gaussian2D {
    27→    mean: vec4<f32>,          // Pixel space (x,y,depth,pad)
    28→    cov: vec4<f32>,           // 2D covariance (xx,xy,yy,pad)
    29→    color: vec4<f32>,         // Linear RGB
    30→    opacity_pad: vec4<f32>,   // Opacity [0,1]
    31→    gaussian_idx_pad: vec4<u32>, // Source index
    32→}
    33→
    34→// Uniforms for backward pass
    35→struct BackwardParams {
    36→    width: u32,          // Full image width (for intermediates indexing)
    37→    height: u32,         // Full image height
    38→    num_gaussians: u32,
    39→    tile_start_x: u32,   // Tile offset in global coordinates
    40→    tile_start_y: u32,   // Tile offset in global coordinates
    41→    tile_width: u32,     // Tile dimensions (for boundary checks)
    42→    tile_height: u32,    // Tile dimensions
    43→    pad: u32,            // Padding for alignment
    44→    background: vec4<f32>,    // Background color
    45→}
    46→
    47→@group(0) @binding(0) var<uniform> params: BackwardParams;
    48→@group(0) @binding(1) var<storage, read> intermediates: array<Contribution>;
    49→@group(0) @binding(2) var<storage, read> gaussians: array<Gaussian2D>;
    50→@group(0) @binding(3) var<storage, read> d_pixels: array<vec4<f32>>;  // Upstream gradients
    51→@group(0) @binding(4) var<storage, read_write> gradient_atomic: array<atomic<i32>>;  // Per-Gaussian gradients as fixed-point i32
    52→@group(0) @binding(5) var<storage, read_write> d_background_pixels: array<vec4<f32>>;  // Per-pixel background gradient contribution (f32, summed on CPU)
    53→
    54→// Maximum contributions per pixel (must match Rust constant)
    55→const MAX_CONTRIBUTIONS_PER_PIXEL: u32 = 16u;
    56→
    57→
    58→// Evaluate 2D Gaussian at a pixel (same as in rasterize.wgsl)
    59→fn eval_gaussian_2d(mean_x: f32, mean_y: f32, cov_xx: f32, cov_xy: f32, cov_yy: f32,
    60→                     pixel_x: f32, pixel_y: f32) -> f32 {
    61→    let dx = pixel_x - mean_x;
    62→    let dy = pixel_y - mean_y;
    63→
    64→    // Compute inverse covariance
    65→    let det = cov_xx * cov_yy - cov_xy * cov_xy;
    66→    if (det <= 0.0) {
    67→        return 0.0;
    68→    }
    69→
    70→    let inv_det = 1.0 / det;
    71→    let inv_xx = cov_yy * inv_det;
    72→    let inv_xy = -cov_xy * inv_det;
    73→    let inv_yy = cov_xx * inv_det;
    74→
    75→    // Quadratic form: (x - μ)^T Σ^-1 (x - μ)
    76→    let quad_form = inv_xx * dx * dx + 2.0 * inv_xy * dx * dy + inv_yy * dy * dy;
    77→
    78→    // Gaussian weight
    79→    return exp(-0.5 * quad_form);
    80→}
    81→
    82→// Zero gradient initializer
    83→fn zero_gradient() -> Gradient {
    84→    return Gradient(
    85→        vec4<f32>(0.0, 0.0, 0.0, 0.0),
    86→        vec4<f32>(0.0, 0.0, 0.0, 0.0),
    87→        vec4<f32>(0.0, 0.0, 0.0, 0.0),
    88→        vec4<f32>(0.0, 0.0, 0.0, 0.0)
    89→    );
    90→}
    91→
    92→// Fixed-point scales for atomic gradient accumulation.
    93→// Different scales for color/opacity vs position/covariance because position
    94→// gradients have more multiplicative factors and are ~100× smaller.
    95→//
    96→// Color/opacity scale (10^7):
    97→// - Color gradients: d_out × alpha × transmittance ≈ 10^-6 × 10^7 = 10 per pixel
    98→// - With 1000 pixels: 10,000 per Gaussian → safe
    99→//
   100→// Position/covariance scale (10^9):
   101→// - Position gradients: d_mean × d_weight ≈ 10^-8 × 10^9 = 10 per pixel
   102→// - With 1000 pixels: 10,000 per Gaussian → safe
   103→// - Higher scale needed because position grads are ~100× smaller than color
   104→const FIXED_POINT_SCALE: f32 = 1e7;
   105→const FIXED_POINT_SCALE_POSITION: f32 = 1e9;
   106→
   107→// Atomic add for color/opacity gradients (scale 10^7)
   108→fn atomic_add_f32(index: u32, value: f32) {
   109→    if (abs(value) < 1e-12) {
   110→        return;
   111→    }
   112→    let scaled = value * FIXED_POINT_SCALE;
   113→    let clamped = clamp(scaled, -2147483647.0, 2147483647.0);
   114→    let fixed = i32(clamped);
   115→    if (fixed != 0) {
   116→        atomicAdd(&gradient_atomic[index], fixed);
   117→    }
   118→}
   119→
   120→// Atomic add for position/covariance gradients (scale 10^9)
   121→// Higher precision needed because these gradients are ~100× smaller
   122→fn atomic_add_f32_position(index: u32, value: f32) {
   123→    if (abs(value) < 1e-14) {
   124→        return;
   125→    }
   126→    let scaled = value * FIXED_POINT_SCALE_POSITION;
   127→    let clamped = clamp(scaled, -2147483647.0, 2147483647.0);
   128→    let fixed = i32(clamped);
   129→    if (fixed != 0) {
   130→        atomicAdd(&gradient_atomic[index], fixed);
   131→    }
   132→}
   133→
   134→// Note: Background gradient is now stored per-pixel (not atomic) to avoid i32 overflow
   135→// when summing across thousands of pixels. The CPU will sum the per-pixel contributions.
   136→
   137→// Gradient buffer layout (16 u32s per Gaussian, each u32 is bitcast f32):
   138→// [0-3]: d_color (vec4<f32> as bitcast u32)
   139→// [4-7]: d_opacity_logit_pad (vec4<f32> as bitcast u32)
   140→// [8-11]: d_mean_px (vec4<f32> as bitcast u32)
   141→// [12-15]: d_cov_2d (vec4<f32> as bitcast u32)
   142→const GRADIENT_STRIDE: u32 = 16u;  // 16 u32s = 64 bytes per Gaussian
   143→
   144→
   145→// Compute gradient of Gaussian 2D evaluation w.r.t. mean
   146→//
   147→// Given weight = exp(-0.5 * quadratic_form), where
   148→// quadratic_form = (x-μ)^T Σ^{-1} (x-μ)
   149→//
   150→// d(weight)/d(μ) = weight * Σ^{-1} (x - μ)
   151→fn gaussian2d_grad_mean(
   152→    mean_x: f32, mean_y: f32,
   153→    cov_xx: f32, cov_xy: f32, cov_yy: f32,
   154→    pixel_x: f32, pixel_y: f32,
   155→    weight: f32
   156→) -> vec2<f32> {
   157→    let dx = pixel_x - mean_x;
   158→    let dy = pixel_y - mean_y;
   159→
   160→    let det = cov_xx * cov_yy - cov_xy * cov_xy;
   161→    if (det <= 0.0) {
   162→        return vec2<f32>(0.0, 0.0);
   163→    }
   164→
   165→    let inv_det = 1.0 / det;
   166→    let inv_xx = cov_yy * inv_det;
   167→    let inv_xy = -cov_xy * inv_det;
   168→    let inv_yy = cov_xx * inv_det;
   169→
   170→    // dw/dμ = weight * Σ^{-1} (x - μ)
   171→    let d_mean_x = weight * (inv_xx * dx + inv_xy * dy);
   172→    let d_mean_y = weight * (inv_xy * dx + inv_yy * dy);
   173→
   174→    return vec2<f32>(d_mean_x, d_mean_y);
   175→}
   176→
   177→// Compute gradient of Gaussian 2D evaluation w.r.t. covariance
   178→//
   179→// d(weight)/d(Σ) = -0.5 * weight * d(quadratic_form)/d(Σ)
   180→//
   181→// Using: quadratic_form = (x-μ)^T Σ^{-1} (x-μ)
   182→// and d(Σ^{-1})/d(Σ) = -Σ^{-1} * dΣ * Σ^{-1}
   183→fn gaussian2d_grad_cov(
   184→    mean_x: f32, mean_y: f32,
   185→    cov_xx: f32, cov_xy: f32, cov_yy: f32,
   186→    pixel_x: f32, pixel_y: f32,
   187→    weight: f32
   188→) -> vec3<f32> {
   189→    let dx = pixel_x - mean_x;
   190→    let dy = pixel_y - mean_y;
   191→
   192→    let det = cov_xx * cov_yy - cov_xy * cov_xy;
   193→    if (det <= 0.0) {
   194→        return vec3<f32>(0.0, 0.0, 0.0);
   195→    }
   196→
   197→    let inv_det = 1.0 / det;
   198→    let inv_xx = cov_yy * inv_det;
   199→    let inv_xy = -cov_xy * inv_det;
   200→    let inv_yy = cov_xx * inv_det;
   201→
   202→    // Outer product: (Σ^{-1} d) ⊗ (Σ^{-1} d)
   203→    let inv_d_x = inv_xx * dx + inv_xy * dy;
   204→    let inv_d_y = inv_xy * dx + inv_yy * dy;
   205→
   206→    // d(quadratic_form)/d(Σ^{-1}) = (x-μ) ⊗ (x-μ)
   207→    // d(Σ^{-1})/d(Σ_xx) = -Σ^{-1}_{·,0} Σ^{-1}_{0,·}
   208→    // This gives d(w)/d(Σ) = 0.5 * w * Σ^{-1} (x-μ) ⊗ Σ^{-1} (x-μ)
   209→
   210→    let d_cov_xx = 0.5 * weight * inv_d_x * inv_d_x;
   211→    let d_cov_xy = 0.5 * weight * inv_d_x * inv_d_y * 2.0; // Factor of 2 for symmetry
   212→    let d_cov_yy = 0.5 * weight * inv_d_y * inv_d_y;
   213→
   214→    return vec3<f32>(d_cov_xx, d_cov_xy, d_cov_yy);
   215→}
