   217→@compute @workgroup_size(16, 16)
   218→fn backward_pass(
   219→    @builtin(global_invocation_id) global_id: vec3<u32>,
   220→    @builtin(workgroup_id) workgroup_id: vec3<u32>,
   221→) {
   222→    // Tile-local coordinates (within this tile)
   223→    let tile_px = global_id.x;
   224→    let tile_py = global_id.y;
   225→
   226→    // Check tile bounds
   227→    if (tile_px >= params.tile_width || tile_py >= params.tile_height) {
   228→        return;
   229→    }
   230→
   231→    // Compute global pixel coordinates (in full image)
   232→    let global_px = params.tile_start_x + tile_px;
   233→    let global_py = params.tile_start_y + tile_py;
   234→
   235→    // Global pixel index (for intermediates lookup in full image)
   236→    let pixel_idx = global_py * params.width + global_px;
   237→
   238→    // Tile-local pixel index (for gradient buffer writes)
   239→    let tile_pixel_idx = tile_py * params.tile_width + tile_px;
   240→
   241→    // Pixel center in global coordinates (for Gaussian evaluation)
   242→    let pixel_x = f32(global_px) + 0.5;
   243→    let pixel_y = f32(global_py) + 0.5;
   244→
   245→    // Get upstream gradient for this pixel
   246→    let d_out = d_pixels[pixel_idx].xyz;
   247→
   248→    // Read contributions for this pixel
   249→    let base_contrib_idx = pixel_idx * MAX_CONTRIBUTIONS_PER_PIXEL;
   250→
   251→    // Count valid contributions
   252→    var num_contribs = 0u;
   253→    for (var i = 0u; i < MAX_CONTRIBUTIONS_PER_PIXEL; i++) {
   254→        let contrib = intermediates[base_contrib_idx + i];
   255→        if (contrib.gaussian_idx == 0xFFFFFFFFu) {
   256→            break;
   257→        }
   258→        num_contribs += 1u;
   259→    }
   260→
   261→    // Blend backward pass (same logic as CPU blend_backward_with_bg)
   262→    //
   263→    // We backpropagate through:
   264→    //   out = sum_i T_i * a_i * c_i + T_final * bg
   265→    //   T_{i+1} = T_i * (1 - a_i)
   266→    //
   267→    // Using reverse-mode accumulation of transmittance gradients.
   268→
   269→    // Initialize g_T_N from background term: out includes T_N * bg
   270→    // dL/dT_N = d_out · bg (because changing T_N changes out by T_N * bg)
   271→    var g_t_next = dot(d_out, params.background.xyz); // dL/d(T_{i+1}) as we go backwards
   272→
   273→    // Process contributions in reverse order
   274→    for (var i = 0u; i < num_contribs; i++) {
   275→        let k = num_contribs - 1u - i;  // Reverse index
   276→        let contrib = intermediates[base_contrib_idx + k];
   277→        let sorted_idx = contrib.gaussian_idx;  // This is the sorted index
   278→        let alpha = contrib.alpha;
   279→        let t_i = contrib.transmittance;
   280→
   281→        // Read Gaussian from sorted array using sorted index
   282→        let g = gaussians[sorted_idx];
   283→
   284→        // Get original Gaussian index for gradient accumulation
   285→        let gaussian_idx = g.gaussian_idx_pad.x;
   286→
   287→        let color = g.color.xyz;
   288→        let opacity = g.opacity_pad.x;
   289→        let mean_x = g.mean.x;
   290→        let mean_y = g.mean.y;
   291→        let cov_xx = g.cov.x;
   292→        let cov_xy = g.cov.y;
   293→        let cov_yy = g.cov.z;
   294→
   295→        // Gradient of output w.r.t. color: dL/dc_i = d_out * (T_i * a_i)
   296→        let d_color = d_out * (t_i * alpha);
   297→
   298→        // Gradient w.r.t. alpha has two parts:
   299→        // (1) Direct from output term: d_out · (T_i * c_i)
   300→        // (2) Indirect via T_{i+1} = T_i * (1 - a_i)
   301→        let direct = dot(d_out, color * t_i);
   302→        let indirect = g_t_next * (-t_i);
   303→        let d_alpha = direct + indirect;
   304→
   305→        // Accumulate gradient for transmittance at position i:
   306→        // dL/dT_i from output term: d_out · (a_i * c_i)
   307→        // dL/dT_i from future transmittance: g_T_{i+1} * (1 - a_i)
   308→        let g_t_i_from_out = dot(d_out, color * alpha);
   309→        let g_t_i_from_next = g_t_next * (1.0 - alpha);
   310→        let g_t_i = g_t_i_from_out + g_t_i_from_next;
   311→        g_t_next = g_t_i;
   312→
   313→        // Chain rule: d_alpha -> d_opacity_logit, d_weight
   314→        //
   315→        // alpha = min(opacity * weight, 0.99)
   316→        // opacity = sigmoid(opacity_logit)
   317→        //
   318→        // We need to recompute weight from the Gaussian evaluation
   319→        let weight = eval_gaussian_2d(
   320→            mean_x, mean_y,
   321→            cov_xx, cov_xy, cov_yy,
   322→            pixel_x, pixel_y
   323→        );
   324→
   325→        // Check if alpha was clamped
   326→        let alpha_raw = opacity * weight;
   327→        let was_clamped = alpha_raw >= 0.99;
   328→
   329→        // d(alpha)/d(opacity) = weight (if not clamped), 0 (if clamped)
   330→        // d(alpha)/d(weight) = opacity (if not clamped), 0 (if clamped)
   331→        let d_opacity = select(d_alpha * weight, 0.0, was_clamped);
   332→        let d_weight = select(d_alpha * opacity, 0.0, was_clamped);
   333→
   334→        // d(sigmoid(x))/dx = sigmoid(x) * (1 - sigmoid(x))
   335→        let d_opacity_logit = d_opacity * opacity * (1.0 - opacity);
   336→
   337→        // Chain rule: d_weight -> d_mean_px, d_cov_2d
   338→        let d_mean = gaussian2d_grad_mean(
   339→            mean_x, mean_y,
   340→            cov_xx, cov_xy, cov_yy,
   341→            pixel_x, pixel_y,
   342→            weight
   343→        );
   344→        let d_cov = gaussian2d_grad_cov(
   345→            mean_x, mean_y,
   346→            cov_xx, cov_xy, cov_yy,
   347→            pixel_x, pixel_y,
   348→            weight
   349→        );
   350→
   351→        // Accumulate to per-Gaussian gradients using atomic operations
   352→        // Each Gaussian has 16 u32s in the gradient_atomic buffer
   353→        let base_idx = gaussian_idx * GRADIENT_STRIDE;
   354→
   355→        // d_color (offsets 0-2 for RGB, 3 is padding)
   356→        atomic_add_f32(base_idx + 0u, d_color.x);
   357→        atomic_add_f32(base_idx + 1u, d_color.y);
   358→        atomic_add_f32(base_idx + 2u, d_color.z);
   359→
   360→        // d_opacity_logit_pad (offset 4 for opacity, 5-7 are padding)
   361→        atomic_add_f32(base_idx + 4u, d_opacity_logit);
   362→
   363→        // d_mean_px (offsets 8-9 for x,y; 10-11 are padding)
   364→        // Use higher precision (10^9) for position gradients
   365→        atomic_add_f32_position(base_idx + 8u, d_mean.x * d_weight);
   366→        atomic_add_f32_position(base_idx + 9u, d_mean.y * d_weight);
   367→
